INSERT INTO "Standard Cost IN" ("SKU", "Versions", "Years", v, ver, is_deleted) SELECT coalesce(k0."SKU", throwIf(isNull(k0."SKU"), 'cells name a member SKU does not have')), coalesce(k1."Versions", throwIf(isNull(k1."Versions"), 'cells name a member Versions does not have')), coalesce(k2."Years", throwIf(isNull(k2."Years"), 'cells name a member Years does not have')), sum(toFloat64(c.value)), toUnixTimestamp64Micro(now64(6)), 0
FROM file('cells/Standard Cost IN.csv', 'CSVWithNames', '"SKU" String, "Versions" String, "Years" String, "value" String') c LEFT JOIN "dim SKU" k0 ON k0.name = c."SKU" LEFT JOIN "dim Versions" k1 ON k1.name = c."Versions" LEFT JOIN "dim Years" k2 ON k2.name = c."Years"
GROUP BY ALL;
